    # Maybe a bipartite graph?

    color = {}
    is_bipartite = True
    for x in U:
        if x not in color:
            stack = [(x, 0)]
            color[x] = 0
            while stack:
                u, c = stack.pop()
                for v in adj[u]:
                    if v not in color:
                        color[v] = 1 - c
                        stack.append((v, 1 - c))
                    elif color[v] == c:
                        is_bipartite = False

    print(f"Is bipartite: {is_bipartite}")

    # Let's see if the graph is actually very simple.
    # Maybe it's a set of isolated points? No, we already saw it's one component.
    # Wait, if the graph is a forest, we can count independent sets easily.

    edges = 0
    for x in U:
        edges += len(adj[x])
    edges //= 2
    print(f"Number of edges: {edges}")
    print(f"Number of vertices: {len(U)}")

